// PT9.8 as written: the in-order worker, and the dedupe table kept on archive (K4). delivery_check.py:
// 1,147 states, at-most-once and in-order hold; exactly-once is liveness, checked from M2.
module delivery

type Msg = M1 | M2
type Status = Unsent | Pending | InFlight | Acked

service machine Delivery {
  state {
    status   : map<Msg, Status> = { M1: Unsent, M2: Unsent }
    req      : map<Msg, 0..2>   = { M1: 0, M2: 0 }            // request copies in the network
    ack      : map<Msg, 0..2>   = { M1: 0, M2: 0 }            // acknowledgement copies in the network
    lost     : map<Msg, 0..1>   = { M1: 0, M2: 0 }            // the network loses at most one copy per message
    seen     : map<Msg, bool>   = { M1: false, M2: false }    // the receiver's dedupe table (K4)
    steps    : map<Msg, 0..2>   = { M1: 0, M2: 0 }            // steps taken at the receiver
    archived : bool = false
  }
  action Emit(m: Msg)     action Send(m: Msg)       action Resend(m: Msg)
  action LoseReq(m: Msg)  action DeliverReq(m: Msg) action LoseAck(m: Msg)
  action DeliverAck(m: Msg)  action Archive()

  on Emit(m) {
    require status[m] == Unsent else reject "emitted"
    require m == M1 || status[M1] != Unsent else reject "emit-order"
    status' = status with [m] = Pending
  }
  on Send(m) {
    require status[m] == Pending && req[m] < 2 else reject "not-pending"
    require m == M1 || status[M1] == Acked else reject "in-order"      // the in-order worker
    status' = status with [m] = InFlight
    req' = req with [m] = req[m] + 1
  }
  on Resend(m) {
    require status[m] == InFlight && req[m] < 2 else reject "not-in-flight"
    req' = req with [m] = req[m] + 1
  }
  on LoseReq(m) {
    require req[m] > 0 && lost[m] < 1 else reject "no-loss"
    req' = req with [m] = req[m] - 1
    lost' = lost with [m] = 1
  }
  on DeliverReq(m) {
    require req[m] > 0 else reject "nothing-in-transit"
    req' = req with [m] = req[m] - 1
    if ack[m] < 2 { ack' = ack with [m] = ack[m] + 1 }
    if !seen[m] { seen' = seen with [m] = true
                  steps' = steps with [m] = steps[m] + 1 }
  }
  on LoseAck(m) {
    require ack[m] > 0 && lost[m] < 1 else reject "no-loss"
    ack' = ack with [m] = ack[m] - 1
    lost' = lost with [m] = 1
  }
  on DeliverAck(m) {
    require ack[m] > 0 else reject "no-ack"
    ack' = ack with [m] = ack[m] - 1
    if status[m] == InFlight { status' = status with [m] = Acked }
  }
  on Archive {
    require !archived && steps[M1] == 1 && steps[M2] == 1 else reject "not-done"
    archived' = true                                  // the dedupe table is kept (K4)
  }

  invariant at-most-once: steps[M1] <= 1 && steps[M2] <= 1
  invariant in-order: steps[M2] >= 1 implies steps[M1] >= 1      // M2 never steps before M1 (S64)
  liveness exactly-once:
    eventually (status[M1] == Acked && status[M2] == Acked && steps[M1] == 1 && steps[M2] == 1)
    under fair { Emit(*), Send(*), Resend(*), DeliverReq(*), DeliverAck(*) }
}
// PT9.8 with a parallel worker: Send does not wait for M1 to be acknowledged. The dedupe table is kept
// on archive, so at-most-once holds (delivery_check.py: 2,368 states). In-order delivery is not claimed.
module delivery

type Msg = M1 | M2
type Status = Unsent | Pending | InFlight | Acked

service machine Delivery {
  state {
    status   : map<Msg, Status> = { M1: Unsent, M2: Unsent }
    req      : map<Msg, 0..2>   = { M1: 0, M2: 0 }            // request copies in the network
    ack      : map<Msg, 0..2>   = { M1: 0, M2: 0 }            // acknowledgement copies in the network
    lost     : map<Msg, 0..1>   = { M1: 0, M2: 0 }            // the network loses at most one copy per message
    seen     : map<Msg, bool>   = { M1: false, M2: false }    // the receiver's dedupe table (K4)
    steps    : map<Msg, 0..2>   = { M1: 0, M2: 0 }            // steps taken at the receiver
    archived : bool = false
  }
  action Emit(m: Msg)     action Send(m: Msg)       action Resend(m: Msg)
  action LoseReq(m: Msg)  action DeliverReq(m: Msg) action LoseAck(m: Msg)
  action DeliverAck(m: Msg)  action Archive()

  on Emit(m) {
    require status[m] == Unsent else reject "emitted"
    require m == M1 || status[M1] != Unsent else reject "emit-order"
    status' = status with [m] = Pending
  }
  on Send(m) {
    require status[m] == Pending && req[m] < 2 else reject "not-pending"
    status' = status with [m] = InFlight
    req' = req with [m] = req[m] + 1
  }
  on Resend(m) {
    require status[m] == InFlight && req[m] < 2 else reject "not-in-flight"
    req' = req with [m] = req[m] + 1
  }
  on LoseReq(m) {
    require req[m] > 0 && lost[m] < 1 else reject "no-loss"
    req' = req with [m] = req[m] - 1
    lost' = lost with [m] = 1
  }
  on DeliverReq(m) {
    require req[m] > 0 else reject "nothing-in-transit"
    req' = req with [m] = req[m] - 1
    if ack[m] < 2 { ack' = ack with [m] = ack[m] + 1 }
    if !seen[m] { seen' = seen with [m] = true
                  steps' = steps with [m] = steps[m] + 1 }
  }
  on LoseAck(m) {
    require ack[m] > 0 && lost[m] < 1 else reject "no-loss"
    ack' = ack with [m] = ack[m] - 1
    lost' = lost with [m] = 1
  }
  on DeliverAck(m) {
    require ack[m] > 0 else reject "no-ack"
    ack' = ack with [m] = ack[m] - 1
    if status[m] == InFlight { status' = status with [m] = Acked }
  }
  on Archive {
    require !archived && steps[M1] == 1 && steps[M2] == 1 else reject "not-done"
    archived' = true                                  // the dedupe table is kept (K4)
  }

  invariant at-most-once: steps[M1] <= 1 && steps[M2] <= 1
  liveness exactly-once:
    eventually (status[M1] == Acked && status[M2] == Acked && steps[M1] == 1 && steps[M2] == 1)
    under fair { Emit(*), Send(*), Resend(*), DeliverReq(*), DeliverAck(*) }
}
// The combinators of poly's embedded surface (PT2.5, S71), as `tsc` checks an embedded module against them.
// They are declarations only: poly-embed reads the module's syntax with the TypeScript compiler API and never
// runs it. A name inside an arrow is a property of its parameter, `$.x`, so `$` is untyped here; the poly
// checker types the program after reading it, as it types the standalone syntax.

declare const node: unique symbol;
interface Node<K extends string> { readonly [node]: K }

export type Decl = Node<'decl'>;
export type Item = Node<'item'>;
export type Stmt = Node<'stmt'>;
export type Arm = Node<'arm'>;
export type Pattern = Node<'pattern'>;
export type Bind = Node<'bind'>;
export type EffItem = Node<'effect-item'>;
export type Instance = Node<'instance'>;
export type Field = Node<'field'>;
export type NameLiteral = Node<'name'>;

/** An expression of PT2.2; the checker types it. */
export type Expr = any;
/** The parameter of an arrow: every name of the program is a property of it. */
export type Scope = any;
export type Arrow<T = Expr> = (scope: Scope) => T;
export type Args = Expr[] | { [name: string]: Expr };
export type Literal = number | string | boolean | NameLiteral;
export type Mode = 'strict' | 'disclosed';

export interface Type {
  /** A parameter's check clause: a set of literals, or a range, and its mode. */
  check(values: Literal[], mode?: Mode): Type;
  check(lo: number, hi: number, mode?: Mode): Type;
}

export declare const t: {
  readonly bool: Type;
  readonly int: Type;
  readonly string: Type;
  range(lo: number, hi: number): Type;
  named(name: string): Type;
  map(key: Type, value: Type): Type;
  ref(machine: string): Type;
  readonly conf: Type;
};

// ── declarations ───────────────────────────────────────────────────────────
export declare function module(name: string, decls: Decl[]): Decl;
export declare function enumType(name: string, members: string[]): Decl;
export declare function union(name: string, ctors: { [ctor: string]: { [payload: string]: Type } }): Decl;
export declare function record(name: string, fields: { [field: string]: Type }): Decl;
export declare function use(path: string): Decl;
export declare function machine(name: string, body: { service?: true; version?: number; state?: { [field: string]: Field }; items?: Item[] }): Decl;
export declare function field(type: Type, init: Arrow, opts?: { check?: Literal[] | { lo: number; hi: number }; mode?: Mode; flag?: 'internal' | 'derived' }): Field;
export declare function name(ctor: string): NameLiteral;
