const toPaying = async (h: any, c: string, n = 1) => {
  await h.open(c);
  for (let i = 0; i < n; i++) await h.add(c);
  await h.checkout(c);
  const [r] = await h.inFlight(); await h.deliver(r.id);
  const [x] = await h.inFlight(); await h.deliver(x.id);
  assert.equal((await h.cart(c)).status, 'paying');
};

test('payment timeout, then charge lands: refund and fail', async () => {
  const h = await fresh();
  await h.open('o');
  assert.equal((await h.paymentTimeout('o')).ok, false);
  assert.equal((await h.paymentTimeout('nope')).ok, false);
  await toPaying(h, 'a', 2);
  assert.deepEqual(await h.paymentTimeout('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'abandoning', items: 2 });
  for (const cmd of ['add', 'checkout', 'cancel', 'returnCart', 'retry', 'abandon', 'paymentTimeout', 'open'])
    assert.equal((await h[cmd]('a')).ok, false, cmd);
  const rel = (await h.inFlight()).find((m: any) => m.action === 'Release');
  assert.deepEqual([rel.from, rel.to, rel.data], ['a', 'inventory', { qty: 2 }]);
  await h.deliver(rel.id);
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  const charge = (await h.inFlight()).find((m: any) => m.action === 'Charge');
  await h.deliver(charge.id);
  assert.equal((await h.payments()).charged, 2);
  const [charged] = await h.inFlight();
  assert.equal(charged.action, 'Charged');
  await h.deliver(charged.id);
  assert.equal((await h.cart('a')).status, 'failed');
  const [refund] = await h.inFlight();
  assert.deepEqual([refund.from, refund.to, refund.action, refund.data], ['a', 'payments', 'Refund', { amount: 2 }]);
  await h.deliverAll();
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
});

test('payment timeout, then decline: fail without refund', async () => {
  const h = await fresh();
  await toPaying(h, 'a');
  await h.declineCards();
  await h.paymentTimeout('a');
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'failed', items: 1 });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: true });
});

