import createHost from '../build/host.gen.ts';

const fresh = async () => (await createHost()) as any;

test('happy path: reserve, charge, paid', async () => {
  const h = await fresh();
  assert.deepEqual(await h.open('a'), { ok: true });
  assert.equal((await h.open('a')).ok, false);
  assert.deepEqual(await h.add('a'), { ok: true });
  assert.deepEqual(await h.add('a'), { ok: true });
  assert.equal((await h.add('a')).ok, false);
  assert.deepEqual(await h.cart('a'), { status: 'open', items: 2 });
  assert.deepEqual(await h.checkout('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'reserving', items: 2 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ from: msgs[0].from, to: msgs[0].to, action: msgs[0].action, data: msgs[0].data },
    { from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 2 } });
  await h.deliver(msgs[0].id);
  assert.deepEqual(await h.cart('a'), { status: 'reserving', items: 2 });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['inventory', 'a', 'Reserved', {}]);
  await h.deliver(r.id);
  assert.equal((await h.cart('a')).status, 'paying');
  const [c] = await h.inFlight();
  assert.deepEqual([c.from, c.to, c.action, c.data], ['a', 'payments', 'Charge', { from: 'a', amount: 2 }]);
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 2 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
});

test('unknown cart refused; empty checkout refused', async () => {
  const h = await fresh();
  assert.equal((await h.add('x')).ok, false);
  assert.equal((await h.cancel('x')).ok, false);
  assert.equal(await h.cart('x'), null);
  await h.open('x');
  assert.equal((await h.checkout('x')).ok, false);
});

test('declined charge keeps units; abandon fails and releases', async () => {
  const h = await fresh();
  assert.equal((await h.acceptCards()).ok, false);
  assert.deepEqual(await h.declineCards(), { ok: true });
  assert.equal((await h.declineCards()).ok, false);
  await h.open('a'); await h.add('a'); await h.checkout('a');
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'declined', items: 1 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 1 });
  for (const cmd of ['add', 'checkout', 'cancel', 'returnCart', 'open']) assert.equal((await h[cmd]('a')).ok, false, cmd);
  assert.deepEqual(await h.abandon('a'), { ok: true });
  assert.equal((await h.cart('a')).status, 'failed');
  assert.equal((await h.retry('a')).ok, false);
  assert.equal((await h.abandon('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: true });
});

test('retry after decline charges again', async () => {
  const h = await fresh();
  await h.open('a'); await h.add('a'); await h.add('a');
  assert.equal((await h.retry('a')).ok, false);
  assert.equal((await h.abandon('a')).ok, false);
  assert.equal((await h.retry('zz')).ok, false);
  await h.declineCards();
  await h.checkout('a'); await h.deliverAll();
  assert.equal((await h.cart('a')).status, 'declined');
  assert.deepEqual(await h.retry('a'), { ok: true });
  assert.equal((await h.cart('a')).status, 'paying');
  const [c] = await h.inFlight();
  assert.deepEqual([c.from, c.to, c.action, c.data], ['a', 'payments', 'Charge', { from: 'a', amount: 2 }]);
  await h.deliverAll();
  assert.equal((await h.cart('a')).status, 'declined');
  await h.acceptCards();
  await h.retry('a'); await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 2 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
});

test('out of stock fails', async () => {
  const h = await fresh();
  for (const c of ['a', 'b']) { await h.open(c); await h.add(c); await h.add(c); await h.checkout(c); }
  await h.deliverAll();
  const st = [(await h.cart('a')).status, (await h.cart('b')).status].sort();
  assert.deepEqual(st, ['failed', 'paid']);
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.equal((await h.payments()).charged, 2);
});

test('cancel while reserving gives units back', async () => {
  const h = await fresh();
  await h.open('a'); await h.add('a'); await h.checkout('a');
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.equal((await h.cart('a')).status, 'cancelling');
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.equal((await h.cart('a')).status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.equal((await h.payments()).charged, 0);
  await h.open('b');
  assert.deepEqual(await h.cancel('b'), { ok: true });
  assert.equal((await h.cart('b')).status, 'cancelled');
});

test('return a paid cart: refund and release', async () => {
  const h = await fresh();
  await h.open('a'); await h.add('a');
  assert.equal((await h.returnCart('a')).ok, false);
  assert.equal((await h.returnCart('nope')).ok, false);
  await h.checkout('a'); await h.deliverAll();
  assert.equal((await h.cart('a')).status, 'paid');
  assert.deepEqual(await h.returnCart('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'returned', items: 1 });
  const msgs = (await h.inFlight()).map((m: any) => [m.from, m.to, m.action, m.data]).sort();
  assert.deepEqual(msgs, [['a', 'inventory', 'Release', { qty: 1 }], ['a', 'payments', 'Refund', { amount: 1 }]]);
  for (const cmd of ['add', 'checkout', 'cancel', 'returnCart', 'open']) assert.equal((await h[cmd]('a')).ok, false, cmd);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  assert.equal((await h.inFlight()).length, 0);
});

test('released units resold before the refund arrives', async () => {
  const h = await fresh();
  await h.open('a'); await h.add('a'); await h.add('a'); await h.checkout('a'); await h.deliverAll();
  await h.returnCart('a');
  const rel = (await h.inFlight()).find((m: any) => m.action === 'Release');
  await h.deliver(rel.id);
  await h.open('b'); await h.add('b'); await h.add('b'); await h.checkout('b');
  for (;;) {
    const next = (await h.inFlight()).find((m: any) => m.action !== 'Refund');
    if (!next) break;
    await h.deliver(next.id);
  }
  assert.equal((await h.cart('b')).status, 'paid');
  assert.equal((await h.payments()).charged, 4);
  await h.deliverAll();
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
});
